      properties: { path: { type: "string", description: "Directory path" } },
      required: ["path"],
    },
  },
  read_file: {
    name: "read_file",
    description: "Read the full contents of a file.",
    parameters: {
      type: "object",
      properties: { path: { type: "string" } },
      required: ["path"],
    },
